import {dimensions,completeRating,validateReview} from './blind-review-model.js';
const $=id=>document.getElementById(id),el=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};let trial,state,index=0;
function persist(){try{localStorage.setItem('btr-review-'+trial.hash,JSON.stringify(state));}catch{$('status').textContent='Device storage unavailable. Keep this tab open and export before leaving.';}}
function save(){const row={case:trial.cases[index].id,A:{},B:{}};for(const s of $('pair').querySelectorAll('select'))row[s.dataset.side][s.dataset.dimension]=s.value?Number(s.value):null;state.ratings[index]=row;persist();}
function render(){const c=trial.cases[index];$('case').value=index;$('progress').textContent=`CASE ${index+1} OF ${trial.cases.length} · ${state.ratings.filter(completeRating).length} completed`;$('question').textContent=c.evidence.question;const e=c.evidence.event;$('plain-evidence').textContent=`${e.type==='shot'?'Shot candidate':'Completed-transfer candidate'} from player ${e.from}${e.to?' to player '+e.to:''}, observed at ${e.end.toFixed(1)} seconds. Current tracking: ${c.evidence.tracking?'available':'lost'}. Goal outcome and tactical intention are not established.`;$('evidence').textContent=JSON.stringify(c.evidence,null,2);$('pair').replaceChildren();for(const side of ['A','B']){const box=el('article','');box.className='arm';box.append(el('h2','Explanation '+side));for(const[role,p]of Object.entries(c.outputs[side]))box.append(el('h3',role),el('p',p.text),el('small','Evidence: '+p.evidence_id));for(const d of dimensions){const label=el('label',d[0].toUpperCase()+d.slice(1));label.className='score-row';const select=el('select','');select.setAttribute('aria-label',side+' '+d);select.dataset.side=side;select.dataset.dimension=d;for(const[n,t]of [['','Choose a score'],['1','1 · Poor'],['2','2 · Weak'],['3','3 · Adequate'],['4','4 · Strong'],['5','5 · Excellent']]){const opt=el('option',t);opt.value=n;select.append(opt);}select.value=state.ratings[index]?.[side]?.[d]||'';select.onchange=()=>{save();$('export').disabled=!state.ratings.filter(completeRating).length||state.ratings.filter(completeRating).length!==trial.cases.length;};label.append(select);box.append(label);}$('pair').append(box);}$('export').disabled=state.ratings.filter(completeRating).length!==trial.cases.length;}
$('start').onclick=()=>{if(!$('independent').checked||!$('familiarity').value){$('status').textContent='Confirm independence and choose your football familiarity to begin.';return;}state.independent=true;state.familiarity=$('familiarity').value;persist();$('setup').hidden=true;$('workspace').hidden=false;render();$('status').textContent='Rate what the evidence supports. Equal scores are welcome.';};
$('case').onchange=()=>{save();index=Number($('case').value);render();};$('next').onclick=()=>{save();if(!completeRating(state.ratings[index])){$('status').textContent='Please rate all three dimensions for both explanations before continuing.';return;}index=(index+1)%trial.cases.length;render();$('status').textContent='Saved on this device. Export the completed review to return your ratings.';};
$('export').onclick=()=>{save();try{validateReview(state,trial);const blob=new Blob([JSON.stringify({...state,exported_at:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a','');a.href=url;a.download=state.reviewer+'-btr-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Exported. Return this file to the person who invited you. Nothing was automatically submitted.';}catch(e){$('status').textContent=e.message;}};
try{const r=await fetch('assets/tracking/blind-trial.json');if(!r.ok)throw Error('Trial is not ready yet');trial=await r.json();try{state=JSON.parse(localStorage.getItem('btr-review-'+trial.hash));}catch{}if(!state||state.trial_hash!==trial.hash)state={trial:trial.id,trial_hash:trial.hash,reviewer:'r-'+crypto.randomUUID(),independent:false,familiarity:'',ratings:[]};$('independent').checked=state.independent;$('familiarity').value=state.familiarity;for(const[i,c]of trial.cases.entries()){const o=el('option',String(i+1));o.value=i;$('case').append(o);}$('status').textContent='Ready. No AI requests or uploads are required.';}catch(e){$('status').textContent=e.message;$('start').disabled=true;}
